name: Release

# Builds, signs (Developer ID), notarizes and staples a distributable
# Cakebrew.app, then attaches the zip to a GitHub release.
#
# Required repository secrets (Settings -> Secrets and variables -> Actions):
#   MACOS_CERTIFICATE_P12    Developer ID Application cert + private key,
#                            exported as .p12 then base64'd:
#                              base64 -i DeveloperID.p12 | pbcopy
#   MACOS_CERTIFICATE_PWD    password used when exporting that .p12
#   KEYCHAIN_PASSWORD        any throwaway string (temp keychain on the runner)
#   APPLE_TEAM_ID            10-character Team ID
#   NOTARY_APPLE_ID          Apple ID used for notarization
#   NOTARY_APP_PASSWORD      app-specific password for that Apple ID
#                            (appleid.apple.com -> Sign-In and Security)
#
# Cakebrew is distributed with Developer ID + hardened runtime and is NOT
# sandboxed — it drives the local `brew` CLI, which the App Sandbox blocks.
# See AGENTS.md ("Distribution & sandboxing") for the measurements behind that.

on:
  push:
    tags: ['v*']
  workflow_dispatch:

permissions:
  contents: write

jobs:
  release:
    name: Build, sign & notarize
    runs-on: macos-26
    steps:
      - name: Checkout
        uses: actions/checkout@v5

      - name: Show toolchain
        run: |
          xcodebuild -version
          xcrun --sdk macosx --show-sdk-version

      - name: Verify signing secrets are present
        env:
          CERT: ${{ secrets.MACOS_CERTIFICATE_P12 }}
          TEAM: ${{ secrets.APPLE_TEAM_ID }}
          NOTARY_USER: ${{ secrets.NOTARY_APPLE_ID }}
        run: |
          missing=""
          [ -n "$CERT" ] || missing="$missing MACOS_CERTIFICATE_P12"
          [ -n "$TEAM" ] || missing="$missing APPLE_TEAM_ID"
          [ -n "$NOTARY_USER" ] || missing="$missing NOTARY_APPLE_ID"
          if [ -n "$missing" ]; then
            echo "::error::Missing required secret(s):$missing — see the header of .github/workflows/release.yml"
            exit 1
          fi

      - name: Import Developer ID certificate
        env:
          MACOS_CERTIFICATE_P12: ${{ secrets.MACOS_CERTIFICATE_P12 }}
          MACOS_CERTIFICATE_PWD: ${{ secrets.MACOS_CERTIFICATE_PWD }}
          KEYCHAIN_PASSWORD: ${{ secrets.KEYCHAIN_PASSWORD }}
        run: |
          set -euo pipefail
          CERT_PATH="$RUNNER_TEMP/certificate.p12"
          KEYCHAIN="$RUNNER_TEMP/build.keychain-db"

          echo -n "$MACOS_CERTIFICATE_P12" | base64 --decode -o "$CERT_PATH"

          security create-keychain -p "$KEYCHAIN_PASSWORD" "$KEYCHAIN"
          security set-keychain-settings -lut 21600 "$KEYCHAIN"
          security unlock-keychain -p "$KEYCHAIN_PASSWORD" "$KEYCHAIN"
          security import "$CERT_PATH" -k "$KEYCHAIN" -P "$MACOS_CERTIFICATE_PWD" \
            -T /usr/bin/codesign -T /usr/bin/security
          # Let codesign use the key without an interactive prompt.
          security set-key-partition-list -S apple-tool:,apple:,codesign: \
            -s -k "$KEYCHAIN_PASSWORD" "$KEYCHAIN" > /dev/null
          security list-keychain -d user -s "$KEYCHAIN" login.keychain-db

          rm -f "$CERT_PATH"
          echo "Imported signing identities:"
          security find-identity -v -p codesigning "$KEYCHAIN" | sed 's/([A-Z0-9]*)/(TEAMID)/'

      - name: Resolve version from the tag
        id: version
        run: |
          set -euo pipefail
          # refs/tags/v1.4 -> 1.4. Fail here rather than publishing something
          # whose About window disagrees with its own release.
          TAG="${GITHUB_REF#refs/tags/}"
          if ! [[ "$TAG" =~ ^v[0-9]+(\.[0-9]+)*$ ]]; then
            echo "::error::tag '$TAG' is not of the form v1.4"
            exit 1
          fi
          echo "marketing=${TAG#v}" >> "$GITHUB_OUTPUT"
          echo "Building version ${TAG#v} (build $GITHUB_RUN_NUMBER)"

      - name: Archive
        env:
          APPLE_TEAM_ID: ${{ secrets.APPLE_TEAM_ID }}
        run: |
          set -euo pipefail
          xcodebuild archive \
            -workspace Cakebrew.xcworkspace \
            -scheme Cakebrew \
            -configuration Release \
            -destination 'platform=macOS' \
            -archivePath "$RUNNER_TEMP/Cakebrew.xcarchive" \
            MARKETING_VERSION="${{ steps.version.outputs.marketing }}" \
            CURRENT_PROJECT_VERSION="$GITHUB_RUN_NUMBER" \
            DEVELOPMENT_TEAM="$APPLE_TEAM_ID" \
            CODE_SIGN_STYLE=Manual \
            CODE_SIGN_IDENTITY="Developer ID Application"

      - name: Export signed app
        env:
          APPLE_TEAM_ID: ${{ secrets.APPLE_TEAM_ID }}
        run: |
          set -euo pipefail
          cat > "$RUNNER_TEMP/exportOptions.plist" <<EOF
          <?xml version="1.0" encoding="UTF-8"?>
          <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
          <plist version="1.0"><dict>
            <key>method</key><string>developer-id</string>
            <key>teamID</key><string>$APPLE_TEAM_ID</string>
            <key>signingStyle</key><string>manual</string>
          </dict></plist>
          EOF
          xcodebuild -exportArchive \
            -archivePath "$RUNNER_TEMP/Cakebrew.xcarchive" \
            -exportOptionsPlist "$RUNNER_TEMP/exportOptions.plist" \
            -exportPath "$RUNNER_TEMP/export"

      - name: Verify the exported versions match the tag
        run: |
          set -euo pipefail
          APP="$RUNNER_TEMP/export/Cakebrew.app"
          HELPER="$APP/Contents/MacOS/CakebrewHelper"
          EXPECTED="${{ steps.version.outputs.marketing }}"

          read_version() {
            /usr/libexec/PlistBuddy -c "Print :CFBundleShortVersionString" "$1" 2>/dev/null
          }

          APP_VERSION=$(read_version "$APP/Contents/Info.plist")
          # The helper is a bundled executable with an embedded plist section.
          HELPER_VERSION=$(otool -s __TEXT __info_plist "$HELPER" \
            | tail -n +3 | awk '{for(i=2;i<=NF;i++) printf "%s", $i}' \
            | xxd -r -p \
            | plutil -extract CFBundleShortVersionString raw -o - - 2>/dev/null || echo "")

          echo "tag=$EXPECTED app=$APP_VERSION helper=$HELPER_VERSION"

          if [ "$APP_VERSION" != "$EXPECTED" ]; then
            echo "::error::app is stamped $APP_VERSION but the tag says $EXPECTED"
            exit 1
          fi
          if [ "$HELPER_VERSION" != "$EXPECTED" ]; then
            echo "::error::embedded helper is stamped $HELPER_VERSION but the tag says $EXPECTED"
            exit 1
          fi

      - name: Verify signature and hardened runtime
        run: |
          set -euo pipefail
          APP="$RUNNER_TEMP/export/Cakebrew.app"
          codesign --verify --strict --verbose=2 "$APP"
          # 'runtime' in the CodeDirectory flags == hardened runtime enabled
          codesign -d --verbose=2 "$APP" 2>&1 | grep -q "flags=.*runtime" \
            && echo "hardened runtime: enabled" \
            || { echo "::error::hardened runtime missing"; exit 1; }

      - name: Notarize and staple
        env:
          NOTARY_APPLE_ID: ${{ secrets.NOTARY_APPLE_ID }}
          NOTARY_APP_PASSWORD: ${{ secrets.NOTARY_APP_PASSWORD }}
          APPLE_TEAM_ID: ${{ secrets.APPLE_TEAM_ID }}
        run: |
          set -euo pipefail
          APP="$RUNNER_TEMP/export/Cakebrew.app"
          ZIP="$RUNNER_TEMP/Cakebrew.zip"

          # ditto (not `zip`) preserves the bundle's symlinks and metadata.
          /usr/bin/ditto -c -k --keepParent "$APP" "$ZIP"

          xcrun notarytool submit "$ZIP" \
            --apple-id "$NOTARY_APPLE_ID" \
            --password "$NOTARY_APP_PASSWORD" \
            --team-id "$APPLE_TEAM_ID" \
            --wait

          xcrun stapler staple "$APP"
          xcrun stapler validate "$APP"

          # Gatekeeper's own verdict on the stapled app.
          spctl --assess --type execute --verbose=2 "$APP"

          # Re-zip *after* stapling so the artifact carries the ticket.
          rm -f "$ZIP"
          /usr/bin/ditto -c -k --keepParent "$APP" "$ZIP"

      - name: Upload build artifact
        uses: actions/upload-artifact@v6
        with:
          name: Cakebrew-notarized
          path: ${{ runner.temp }}/Cakebrew.zip
          if-no-files-found: error

      - name: Attach to GitHub release
        if: startsWith(github.ref, 'refs/tags/')
        uses: softprops/action-gh-release@v3
        with:
          files: ${{ runner.temp }}/Cakebrew.zip
          generate_release_notes: true
//
//  BPLocalizationParityTests.m
//  CakebrewTests
//
//  A key present in en.lproj and missing elsewhere does not fall back to
//  English — NSLocalizedString returns the key itself, so a German user sees
//  "Formula_All_Dependents_Title" on screen. Four keys were in exactly that
//  state before #75.
//
//  Nothing mechanical caught it, so this does: every locale must carry every
//  English key, and the check is verified against synthetic data so a broken
//  check cannot pass vacuously.
//

#import <XCTest/XCTest.h>

@interface BPLocalizationParityTests : XCTestCase
@end

@implementation BPLocalizationParityTests

- (NSString *)localizationsDirectory
{
	NSString *repoRoot = [[@(__FILE__) stringByDeletingLastPathComponent] stringByDeletingLastPathComponent];
	return [repoRoot stringByAppendingPathComponent:@"Cakebrew"];
}

/// key -> value for one .strings file, parsed from source rather than the
/// built bundle so a missing key is caught before it ships.
+ (NSDictionary<NSString *, NSString *> *)stringsAtPath:(NSString *)path
{
	NSString *contents = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:NULL];
	if (contents.length == 0)
	{
		return @{};
	}

	NSRegularExpression *entry =
		[NSRegularExpression regularExpressionWithPattern:@"^\"([^\"]+)\"\\s*=\\s*\"((?:[^\"\\\\]|\\\\.)*)\";"
												  options:NSRegularExpressionAnchorsMatchLines
													error:NULL];
	NSMutableDictionary *strings = [NSMutableDictionary dictionary];
	[entry enumerateMatchesInString:contents options:0 range:NSMakeRange(0, contents.length)
						 usingBlock:^(NSTextCheckingResult *match, NSMatchingFlags flags, BOOL *stop) {
		strings[[contents substringWithRange:[match rangeAtIndex:1]]] =
			[contents substringWithRange:[match rangeAtIndex:2]];
	}];
	return strings;
}

/// Keys in `base` that `locale` does not carry.
+ (NSArray<NSString *> *)keysMissingFromLocale:(NSDictionary *)locale comparedTo:(NSDictionary *)base
{
	NSMutableArray<NSString *> *missing = [NSMutableArray array];
	for (NSString *key in base)
	{
		if (!locale[key])
		{
			[missing addObject:key];
		}
	}
	return [missing sortedArrayUsingSelector:@selector(compare:)];
}

- (NSArray<NSString *> *)localeDirectoryNames
{
	NSArray *entries = [[NSFileManager defaultManager] contentsOfDirectoryAtPath:[self localizationsDirectory] error:NULL];
	NSMutableArray *locales = [NSMutableArray array];
	for (NSString *entry in entries)
	{
		if ([entry hasSuffix:@".lproj"])
		{
			[locales addObject:entry];
		}
	}
	return locales;
}

- (void)testTheCheckItselfDetectsAMissingKey
{
	// Guards the guard: verified against synthetic data, so the real assertion
	// below cannot pass because the comparison is broken.
	NSDictionary *base = @{ @"a": @"A", @"b": @"B" };
	NSDictionary *complete = @{ @"a": @"A", @"b": @"traduit" };
	NSDictionary *incomplete = @{ @"a": @"A" };

	XCTAssertEqual([[self class] keysMissingFromLocale:complete comparedTo:base].count, 0u);
	XCTAssertEqualObjects([[self class] keysMissingFromLocale:incomplete comparedTo:base], (@[ @"b" ]));
}

- (void)testTheParserReadsRealEntries
{
	NSString *path = [[self localizationsDirectory] stringByAppendingPathComponent:@"en.lproj/Localizable.strings"];
	NSDictionary *english = [[self class] stringsAtPath:path];

	XCTAssertGreaterThan(english.count, 100u, @"the parser should read the whole English file");
	XCTAssertNotNil(english[@"Sidebar_Item_Services"], @"a known key should be present");
}

- (void)testDetailPlaceholderAndExportFailureHaveReadableEnglishDefaults
{
	NSString *root = [self localizationsDirectory];
	for (NSString *locale in @[@"en", @"de", @"fr", @"it", @"pt", @"zh-Hans"])
	{
		NSString *path = [root stringByAppendingPathComponent:
			[NSString stringWithFormat:@"%@.lproj/Localizable.strings", locale]];
		NSDictionary *strings = [[self class] stringsAtPath:path];
		XCTAssertNotNil(strings[@"Info_View_Empty_Value"], @"%@ needs the detail placeholder", locale);
		XCTAssertNotNil(strings[@"Brewfile_Export_Failed"], @"%@ needs the export failure caption", locale);
		if ([locale isEqualToString:@"en"])
		{
			XCTAssertEqualObjects(strings[@"Info_View_Empty_Value"], @"--");
			XCTAssertEqualObjects(strings[@"Brewfile_Export_Failed"], @"Export Failed");
		}
	}
}

- (void)testEveryLocaleCarriesEveryEnglishKey
{
	NSString *root = [self localizationsDirectory];
	NSDictionary *english = [[self class] stringsAtPath:
							 [root stringByAppendingPathComponent:@"en.lproj/Localizable.strings"]];
	XCTAssertGreaterThan(english.count, 0u);

	NSArray *locales = [self localeDirectoryNames];
	XCTAssertGreaterThanOrEqual(locales.count, 6u, @"all six localizations should be scanned");

	NSMutableArray<NSString *> *problems = [NSMutableArray array];
	for (NSString *locale in locales)
	{
		if ([locale isEqualToString:@"en.lproj"] || [locale isEqualToString:@"Base.lproj"])
		{
			continue;
		}

		NSString *path = [root stringByAppendingPathComponent:
						  [locale stringByAppendingPathComponent:@"Localizable.strings"]];
		NSArray *missing = [[self class] keysMissingFromLocale:[[self class] stringsAtPath:path]
													comparedTo:english];
