    10	class LocalizationDebtTests < Minitest::Test
    11	  ROOT = File.expand_path('../..', __dir__)
    12	  SCRIPT = File.join(ROOT, 'scripts/localization-debt.rb')
    13	  LOCALES = %w[de en fr it pt zh-Hans].freeze
    14	
    15	  def setup
    16	    @root = Dir.mktmpdir('cakebrew-l10n-test-')
    17	    @metadata = File.join(@root, 'metadata.json')
    18	    LOCALES.each { |locale| strings(locale, '"z" = "z"; "a" = "a"; "brand" = "Cakebrew"; "different" = "English";') }
    19	    strings('de', '"z" = "z"; "a" = "a"; "brand" = "Cakebrew"; "different" = "Deutsch";')
    20	    metadata('placeholders' => [{ 'key' => 'a', 'locales' => ['de'], 'reason' => 'New English placeholder.' }],
    21	             'intentional' => [{ 'key' => 'brand', 'locales' => ['de'], 'reason' => 'Product name.' }])
    22	  end
    23	
    24	  def teardown
    25	    FileUtils.remove_entry(@root)
    26	  end
    27	
    28	  def strings(locale, source)
    29	    path = File.join(@root, 'Cakebrew', "#{locale}.lproj", 'Localizable.strings')
    30	    FileUtils.mkdir_p(File.dirname(path))
    31	    File.write(path, source)
    32	  end
    33	
    34	  def metadata(overrides = {})
    35	    File.write(@metadata, JSON.generate({ 'version' => 1, 'placeholders' => [], 'intentional' => [] }.merge(overrides)))
    36	  end
    37	
    38	  def run_report(*arguments, env: {}, default_root: false)
    39	    paths = default_root ? [] : ['--root', @root, '--metadata', @metadata]
    40	    Open3.capture3(env, RbConfig.ruby, SCRIPT, *paths, *arguments, chdir: @root)
    41	  end
    42	
    43	  def report
    44	    out, err, status = run_report('--json')
    45	    assert status.success?, err
    46	    JSON.parse(out)
    47	  end
    48	
    49	  def assert_invalid(fragment)
    50	    out, err, status = run_report('--json')
    51	    refute status.success?, 'Invalid input must fail instead of reporting zero debt.'
    52	    assert_empty out
    53	    assert_includes err, fragment
    54	  end
    55	
    56	  def test_classification_counts_and_debt_do_not_fail
    57	    data = report
    58	    assert_equal 4, data.fetch('english_keys')
    59	    de = data.fetch('locales').fetch('de')
    60	    assert_equal ['a'], de.fetch('placeholders')
    61	    assert_equal ['brand'], de.fetch('intentional')
    62	    assert_equal ['z'], de.fetch('unreviewed_equal')
    63	    assert_equal ['different'], de.fetch('different')
    64	    assert_equal [], de.fetch('missing')
    65	    assert_equal [], de.fetch('extra')
        lines += ['', "### #{category} (#{row['counts'][category]})", '', '<pre>']
        row[category].each { |key| lines << "  #{CGI.escapeHTML(JSON.generate(key))}" }
        lines << '</pre>'
      end
    end
    lines.join("\n") + "\n"
  end

  def self.main(arguments)
    root = File.expand_path('..', __dir__)
    metadata_path = File.join(__dir__, 'localization-debt.json')
    json = false
    summary = nil
    parser = OptionParser.new do |options|
      options.banner = 'Usage: ruby scripts/localization-debt.rb [--root PATH] [--metadata PATH] [--json] [--summary PATH]'
      options.on('--root PATH') { |path| root = File.expand_path(path) }
      options.on('--metadata PATH') { |path| metadata_path = File.expand_path(path) }
      options.on('--json') { json = true }
      options.on('--summary PATH') { |path| summary = path }
    end
    parser.parse!(arguments)
    raise InvalidInput, "unexpected arguments: #{arguments.inspect}" unless arguments.empty?
    data = report(root, metadata_path)
    text = markdown(data)
    File.open(summary, 'a') { |file| file.write(text) } if summary
    puts(json ? JSON.pretty_generate(data) : text)
    0
  rescue InvalidInput, OptionParser::ParseError, SystemCallError, EncodingError => error
    # JSON quoting prevents input filenames/diagnostics from becoming CI commands.
    warn "Localization report error: #{JSON.generate(error.message)}"
    1
  end
end

exit LocalizationDebt.main(ARGV) if $PROGRAM_NAME == __FILE__
