+    BPUpgradePlan *plan = [[BPUpgradePlan alloc] initWithSelection:formulae];
+    __block BOOL attempted = NO;
+    BOOL succeeded = [plan executeWithProgress:progress runner:^BOOL(NSArray<NSString *> *arguments) {
+        attempted = YES;
